// Hand-written. Not generated by Speakeasy.
//
// Covers the mTLS certificate subject type handling. See
// internal/provider/planmodifiers/mtls_subject.go for the problem.
package provider

import (
	"context"
	"testing"

	"github.com/authlete/terraform-provider-authlete/internal/provider/planmodifiers"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

// TestSubjectTypeAttributesExist guards the list against a rename. If an
// attribute disappears from the schema the modifier and validator silently stop
// covering it, and switching subject type starts failing again with A032216.
func TestSubjectTypeAttributesExist(t *testing.T) {
	attrs := resourceSchema(t, NewClientResource()).Attributes
	for _, name := range planmodifiers.MTLSSubjectAttributes {
		if _, ok := attrs[name]; !ok {
			t.Errorf("authlete_client has no %q attribute.\n\n"+
				"MTLSSubjectAttributes in internal/provider/planmodifiers is out of step "+
				"with the schema, so this subject type is no longer cleared when "+
				"superseded.", name)
		}
	}
}

// TestSubjectTypesCarryTheModifier is the direct guard on the overlay. The
// x-speakeasy-plan-modifiers entries could be dropped by an overlay edit and
// nothing else would notice: the provider still builds and every test that does
// not switch subject type still passes.
func TestSubjectTypesCarryTheModifier(t *testing.T) {
	attrs := resourceSchema(t, NewClientResource()).Attributes
	for _, name := range planmodifiers.MTLSSubjectAttributes {
		attr, ok := attrs[name].(schema.StringAttribute)
		if !ok {
			t.Errorf("%s is not a string attribute", name)
			continue
		}
		if len(attr.PlanModifiers) == 0 {
			t.Errorf("%s has no plan modifier.\n\n"+
				"Switching away from this subject type will send the stale value "+
				"alongside the new one and Authlete will reject it with A032216. The "+
				"only escape for the customer is replacing the client, which changes "+
				"its client_id.\n\n"+
				"Restore the x-speakeasy-plan-modifiers entry for this property in "+
				".speakeasy/terraform_overlay.yaml.", name)
		}
	}
}

// TestClientRefusesTwoSubjectTypes checks the validator is registered. Its
// behaviour with real configuration needs the framework's test harness; this
// guards the wiring, which is what an edit would break.
func TestClientRefusesTwoSubjectTypes(t *testing.T) {
	r, ok := NewClientResource().(resource.ResourceWithConfigValidators)
	if !ok {
		t.Fatal("ClientResource no longer declares ConfigValidators, so a configuration " +
			"naming two certificate subject types reaches Authlete and comes back as " +
			"A032216 without naming the conflicting attributes")
	}
	if len(r.ConfigValidators(context.Background())) == 0 {
		t.Error("ClientResource has no config validators registered")
	}
}
